function renderSectionMini(){const p=parcel(),box=$('#section-mini');if(!p||!box){if(box)box.innerHTML='';return}const t=planTransform(p.vertices),b=p.bounds||bbox(p.vertices),pc=Number($('#section-position').value||50)/100,axis=viewer.sectionAxis,cut=axis==='ns'?b.minX+(b.maxX-b.minX)*pc:b.minY+(b.maxY-b.minY)*pc;let a,c;if(axis==='ns'){a=t.p([cut,b.minY]);c=t.p([cut,b.maxY])}else{a=t.p([b.minX,cut]);c=t.p([b.maxX,cut])}box.innerHTML=`<svg viewBox="0 0 1000 680"><path d="${pathD(p.vertices,t)}" fill="#f7f8ef" stroke="#60745d" stroke-width="2"/><line x1="${a[0]}" y1="${a[1]}" x2="${c[0]}" y2="${c[1]}" stroke="#9a6b40" stroke-width="3" stroke-dasharray="12 8"/></svg>`}function renderTechnical(){let html='';if(viewer.tech==='solar-plan')html=window.V14Solar.planSVG();else if(viewer.tech==='solar-chart')html=window.V14Solar.chartSVG();else if(viewer.tech==='siteplan')html=renderPlanView(true);else if(viewer.tech==='plan')html=renderPlanView(false);else if(viewer.tech==='section')html=renderSection('ns');else if(viewer.tech==='section-ew')html=renderSection('ew');else if(viewer.tech?.startsWith('elevation-')){const d=viewer.tech.split('-')[1],nm={north:'Nord',south:'Sud',east:'Est',west:'Ouest'}[d];html=renderElevation(nm)}$('#technical-stage').innerHTML=html;const svg=$('#technical-stage svg');if(svg)svg.style.transform=`translate(${viewer.techPanX}px,${viewer.techPanY}px) scale(${viewer.techZoom})`;renderSectionMini()}
