surface.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea,button'))return;const step=Math.PI/18;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','=','Home',' '].includes(e.key))e.preventDefault();if(e.key==='Home'){$('#model-reset').click();return;}if(e.key===' '){$('#auto-rotate').click();return;}const pan=isTechnical()||e.shiftKey,px=isTechnical()?'techPanX':'panX',py=isTechnical()?'techPanY':'panY';if(e.key.startsWith('Arrow')){stopRotation();if(pan){viewer[px]+=(e.key==='ArrowLeft'?-24:e.key==='ArrowRight'?24:0);viewer[py]+=(e.key==='ArrowUp'?-24:e.key==='ArrowDown'?24:0);}else{viewer.yaw+=(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0);viewer.pitch+=(e.key==='ArrowUp'?step:e.key==='ArrowDown'?-step:0);}}if(['+','=','-'].includes(e.key)){const k=isTechnical()?'techZoom':'zoom';viewer[k]=Math.max(.35,Math.min(5,viewer[k]*(e.key==='-'?1/1.2:1.2)));}renderViewer();syncOrbit();});
$('#orbit-pitch').min=-180;$('#orbit-pitch').max=180;const origSync=syncOrbit;function syncOrbit(){const deg=x=>((x*180/Math.PI+180)%360+360)%360-180;$('#orbit-yaw').value=((viewer.yaw*180/Math.PI)%360+360)%360;$('#orbit-pitch').value=deg(viewer.pitch);$('#orbit-roll').value=((viewer.roll*180/Math.PI)%360+360)%360;for(const k of ['yaw','pitch','roll'])$('#'+k+'-value').textContent=Math.round(Number($('#orbit-'+k).value))+'°';}
