async function inspectFile(file){const e=ext(file.name),rec={id:uid('pending'),file,name:file.name,type:sourceType(file.name),size:file.size,parsed:null,summary:'Source conservée'};if(file.size>16*1024*1024)throw Error('La copie locale de cette source dépasse 16 Mo.');rec.dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});if(e==='kml'){rec.parsed=parseKML(await file.text(),file.name);rec.summary=rec.parsed.summary;}else if(e==='json'||e==='geojson'){try{rec.parsed=parseJSON(await file.text(),file.name);rec.summary=rec.parsed.summary;}catch(err){rec.summary='Document JSON : '+err.message;}}else if(e==='kmz'){try{const text=await unzipKml(await file.arrayBuffer());rec.parsed=parseKML(text,file.name);rec.summary=rec.parsed.summary+' · KML extrait du KMZ';}catch(err){rec.summary='KMZ : '+err.message;}}return rec;}
async function unzipKml(buffer){const bytes=new Uint8Array(buffer),v=new DataView(buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('Archive ZIP invalide');let pos=v.getUint32(end+16,true),count=v.getUint16(end+10,true);for(let j=0;j<count;j++){if(v.getUint32(pos,true)!==0x02014b50)break;const method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),unpacked=v.getUint32(pos+24,true),nl=v.getUint16(pos+28,true),xl=v.getUint16(pos+30,true),cl=v.getUint16(pos+32,true),off=v.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nl));if(/\.kml$/i.test(name)){if(unpacked>20*1024*1024)throw Error('KML trop volumineux');const start=off+30+v.getUint16(off+26,true)+v.getUint16(off+28,true),data=bytes.slice(start,start+size);if(method===0)return new TextDecoder().decode(data);if(method!==8)throw Error('Compression non prise en charge');return await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text();}pos+=46+nl+xl+cl;}throw Error('Aucun KML dans le KMZ');}
function renderSavedSources(){const box=$('#project-sources-saved'),a=sourceList();box.innerHTML='';$('#project-source-count').textContent=a.length;for(const s of a){const r=document.createElement('div');r.className='project-import-source-row';r.innerHTML=`<b>${esc(s.name)}</b><button data-preview-source="${esc(s.id)}">Ouvrir</button>${s.dataUrl?`<button data-download-source="${esc(s.id)}">Télécharger</button>`:''}<button class="source-delete" data-delete-source="${esc(s.id)}">Suppr.</button><small>${esc(s.type)} · ${esc(s.summary||'Source du projet')}</small>`;box.appendChild(r);}window.V14Documents?.refresh();}

