function closeViewerMenu(name,restoreFocus=false){$('#'+name+'-menu').classList.remove('open');$('#'+name+'-toggle').setAttribute('aria-expanded','false');if(restoreFocus)$('#'+name+'-toggle').focus({preventScroll:true});}
