function openViewerMenu(name){for(const other of ['views','technical-drawings'])if(other!==name)closeViewerMenu(other);$('#'+name+'-menu').classList.add('open');$('#'+name+'-toggle').setAttribute('aria-expanded','true');}
for(const name of ['views','technical-drawings']){
 const menu=$('#'+name+'-menu'),toggle=$('#'+name+'-toggle');
 toggle.onclick=()=>{if(menu.classList.contains('open'))closeViewerMenu(name);else openViewerMenu(name);};
 menu.addEventListener('keydown',e=>{
  const open=menu.classList.contains('open');
  if(e.key==='Escape'&&open){e.preventDefault();e.stopPropagation();closeViewerMenu(name,true);return;}
  if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&(open||e.target===toggle)){
   e.preventDefault();if(!open)openViewerMenu(name);
   const items=[...$('#'+name+'-list').querySelectorAll('button:not(:disabled)')].filter(b=>b.getAttribute('aria-disabled')!=='true');
   if(!items.length)return;const index=items.indexOf(document.activeElement);
   const next=e.key==='Home'?0:e.key==='End'?items.length-1:index<0?(e.key==='ArrowUp'?items.length-1:0):(index+(e.key==='ArrowUp'?-1:1)+items.length)%items.length;
   items[next].focus();
  }
 });
}
