      img.onload=()=>{if(token!==state.token)return;zoomControls(true);fit();};
      img.onerror=()=>{if(token!==state.token)return;state.image=null;content.className='';zoomControls(false);status('Aperçu indisponible pour cette image. Le fichier original reste téléchargeable.');};
