  async function openReader(id,ids){if(!bindProject()||!all().some(s=>s.id===id))return;state.ids=ids.filter(x=>all().some(s=>s.id===x));if(!state.ids.includes(id))state.ids.push(id);state.current=id;if(!reader.open)reader.showModal();reveal();await renderReader();}
