  browser.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.docFilter){state.category=b.dataset.docFilter;renderBrowser();}if(b.dataset.openDocument)openReader(b.dataset.openDocument,filtered().map(s=>s.id));if(b.dataset.archiveDocument){const s=all().find(x=>x.id===b.dataset.archiveDocument);if(!s)return;const m=metadata();m[s.id]={...(m[s.id]||{}),archived:category(s)!=='Archives',updated:new Date().toISOString()};domainSet('documentIndex',m);renderBrowser();}});
  browser.addEventListener('change',e=>{const id=e.target.dataset.documentCategory;if(!id||!classifications.includes(e.target.value))return;const m=metadata();m[id]={...(m[id]||{}),category:e.target.value,updated:new Date().toISOString()};domainSet('documentIndex',m);renderBrowser();});
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.previewSource||b.dataset.downloadSource;if(!id)return;const s=all().find(x=>x.id===id);if(!s)return;if(b.dataset.downloadSource)download(s);else openReader(id,all().map(s=>s.id));});
  reader.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(['ArrowLeft','ArrowRight','+','=','-','Home'].includes(e.key)){e.preventDefault();e.stopPropagation();if(e.key==='ArrowLeft')step(-1);if(e.key==='ArrowRight')step(1);if(e.key==='+'||e.key==='=')zoom(state.zoom+.25);if(e.key==='-')zoom(state.zoom-.25);if(e.key==='Home')fit();}});
  const measureGesture=()=>{const a=[...pointers.values()];return a.length>1?{center:[(a[0][0]+a[1][0])/2,(a[0][1]+a[1][1])/2],distance:Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1])}:a.length?{center:a[0],distance:0}:null;};
  content.addEventListener('pointerdown',e=>{if(!state.image?.naturalWidth||e.button!==0)return;e.preventDefault();content.focus();content.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);state.gesture=measureGesture();});
