  window.addEventListener('resize',()=>{if(browser.open||reader.open)requestAnimationFrame(reveal);});
  $('#show-source-plan').onclick=()=>openBrowser('Sources');$('#show-source-section').onclick=()=>openBrowser('Tout');$('#open-sources-bottom').onclick=()=>openBrowser('Sources');
  const browse=document.createElement('button');browse.id='v14-browse-imported';browse.className='v14-doc-button';browse.textContent='Parcourir les documents et archives';browse.onclick=()=>{$('#project-import-dialog').close();openBrowser('Tout');};$('#project-sources-saved').before(browse);
  window.V14Documents={open:openBrowser,close,refresh};
