 function zoom(delta){if(!center)return;z=Math.max(tilejson?.minzoom||1,Math.min(tilejson?.maxzoom||20,z+delta));draw();}
 el.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1:-1);},{passive:false});
 el.addEventListener('pointerdown',e=>{if(e.target.closest('button,a')||!center)return;e.preventDefault();el.setPointerCapture(e.pointerId);points.set(e.pointerId,[e.clientX,e.clientY]);const ps=[...points.values()];gesture={center:merc(...center,z),z,mid:ps.length===1?ps[0]:[(ps[0][0]+ps[1][0])/2,(ps[0][1]+ps[1][1])/2],distance:ps.length>1?Math.hypot(ps[0][0]-ps[1][0],ps[0][1]-ps[1][1]):0};});
 el.addEventListener('pointermove',e=>{if(!points.has(e.pointerId)||!gesture)return;points.set(e.pointerId,[e.clientX,e.clientY]);const ps=[...points.values()],mid=ps.length===1?ps[0]:[(ps[0][0]+ps[1][0])/2,(ps[0][1]+ps[1][1])/2];if(ps.length>1&&gesture.distance){const d=Math.hypot(ps[0][0]-ps[1][0],ps[0][1]-ps[1][1]);z=Math.max(1,Math.min(tilejson?.maxzoom||20,gesture.z+Math.round(Math.log2(d/gesture.distance))));}else z=gesture.z;const factor=2**(z-gesture.z);center=geo(gesture.center[0]*factor-(mid[0]-gesture.mid[0]),gesture.center[1]*factor-(mid[1]-gesture.mid[1]),z);center[1]=Math.max(-85,Math.min(85,center[1]));draw();});
 const end=e=>{points.delete(e.pointerId);gesture=null;if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);
 el.addEventListener('keydown',e=>{if(e.target!==el||!center)return;if(['+','=','-','Home','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='Home')fit();else if(['+','=','-'].includes(e.key))zoom(e.key==='-'?-1:1);else{const c=merc(...center,z);center=geo(c[0]+(e.key==='ArrowLeft'?-40:e.key==='ArrowRight'?40:0),c[1]+(e.key==='ArrowUp'?-40:e.key==='ArrowDown'?40:0),z);draw();}}});
 $('#solar-map-plus').onclick=()=>zoom(1);$('#solar-map-minus').onclick=()=>zoom(-1);$('#solar-map-fit').onclick=fit;$('#solar-map-load').onclick=load;$('#solar-map-configure').onclick=()=>{if(window.ParcoursSolarHost)onConfigure();else status.textContent='Configurez MapTiler dans Parcelle du fichier Parcours.';};
 const observer=new ResizeObserver(()=>{if(getState().panel)draw();});observer.observe(el);
