 function pause(save=true){playing=false;cancelAnimationFrame(handle);handle=0;const el=$('#solar-play');if(el){el.setAttribute('aria-pressed','false');el.textContent='▶ Animer';}if(save&&project===activeId())persist();}
 function play(){
  if(playing){pause();return;}const s=snapshot();if(s.error)return;stopRotation();state.enabled=true;playing=true;last=0;elapsed=0;$('#solar-play').setAttribute('aria-pressed','true');$('#solar-play').textContent='Ⅱ Pause';
  const tick=t=>{if(!playing)return;if(last)elapsed+=Math.min(t-last,250);last=t;if(elapsed>=140){const jump=state.animation==='year'?1:5;elapsed=0;
    try{if(state.animation==='year')state.date=core.addDays(state.date,jump*Number(state.speed));else{const site=location();let ms=core.resolveTime(state.date,state.time,site.timezone).ms+jump*Number(state.speed)*60000;let local=core.localParts(ms,site.timezone);if(local.date!==state.date)ms=core.dayBounds(state.date,site.timezone)[0];if(state.daytime){for(let i=0;i<300&&core.position(ms,site.lat,site.lon).elevation<=0;i++)ms+=5*60000;if(core.localParts(ms,site.timezone).date!==state.date){const e=events(site);ms=e.sunrise?e.sunrise+10*60000:core.resolveTime(state.date,'12:00',site.timezone).ms;}}state.time=core.localParts(ms,site.timezone).time;}
     if(Number(state.date.slice(0,4))>2099){state.date='2099-12-30';pause();return;}redraw(false);
    }catch{pause();return;}
   }handle=requestAnimationFrame(tick);
  };handle=requestAnimationFrame(tick);
 }
